def main(filename, **kwargs):
    if not filename or filename == '-':
        text = sys.stdin.read()
    else:
        text = Path(filename).read_text()
    parser = grammardefaultParser()
    return parser.parse(
        text,
        filename=filename,
        **kwargs,
    )


